use safety;

CREATE TABLE safety.ytsafety_sys_user_factory (
  `id` BIGINT(20) NOT NULL,
  `user_id` BIGINT(20) NULL COMMENT '用户主键',
  `factory_id` BIGINT(20) NULL COMMENT '厂区主键',
  `factory_code` VARCHAR(20) NULL COMMENT '厂区编码',
  `factory_name` VARCHAR(50) NULL COMMENT '厂区名称',
  `create_time` DATETIME NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT = '用户授权厂区表';

CREATE TABLE safety.ytsafety_sys_user_depart (
  `id` BIGINT(20) NOT NULL,
  `user_id` BIGINT(20) NULL COMMENT '用户主键',
  `depart_id` BIGINT(20) NULL COMMENT '部门主键',
  `depart_code` BIGINT(20) NULL COMMENT '部门编码',
  `depart_name` VARCHAR(100) NULL COMMENT '部门名称',
  `create_time` DATETIME NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT = '用户授权部门表';

CREATE TABLE safety.ytsafety_sys_user_data_rule (
  `id` bigint(20) NOT NULL,
  `user_id` bigint(20) DEFAULT NULL COMMENT '用户主键',
  `perm_id` bigint(20) DEFAULT NULL COMMENT '菜单主键',
  `field_code` varchar(20) DEFAULT NULL,
  `field_name` varchar(50) DEFAULT NULL COMMENT '字段名称',
  `relation` varchar(50) DEFAULT NULL COMMENT '关系: or 或 and 且',
  `rule_conditions` varchar(50) DEFAULT NULL COMMENT '>,=,!=,like',
  `rule_value` varchar(50) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_user` varchar(64) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_user` varchar(64) DEFAULT NULL COMMENT '修改人',
  `del_flag` tinyint(1) DEFAULT 0 COMMENT '状态：0启用 1删除',
  `version` int(11) DEFAULT 0 COMMENT '修改版本',
  `sort` int(5) DEFAULT NULL COMMENT '排序',
  `perm_code` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户菜单数据规则表';

CREATE TABLE safety.ytsafety_sys_responsible (
  `id` BIGINT(20) NOT NULL COMMENT '主键',
  `user_id` BIGINT(20) NULL COMMENT '用户主键',
  `emp_name` VARCHAR(50) NULL COMMENT '用户名',
  `emp_no` VARCHAR(20) NULL COMMENT '员工号',
  `user_type` TINYINT(1) comment '人员类型 0 非保卫 1 保卫人员',
  `valid_period` DATETIME NULL COMMENT '有效期',
  `update_source` INT NULL COMMENT '更新来源：0 手工创建 1 EHR匹配',
  `status` INT NULL COMMENT '状态:0 正常 1 禁用',
  `remark` VARCHAR(1000) NULL COMMENT '备注',
  `create_time` DATETIME NULL COMMENT '创建时间',
  `create_user` VARCHAR(64) NULL COMMENT '创建人',
  `update_time` DATETIME NULL COMMENT '修改时间',
  `update_user` VARCHAR(64) NULL COMMENT '修改人',
  `del_flag` TINYINT(1)  DEFAULT 0 DEFAULT 0  COMMENT '删除标识',
  `version` INT  DEFAULT 0 DEFAULT 0 COMMENT '修改版本',
  PRIMARY KEY (`id`)) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT = '安全责任信息表';

CREATE TABLE safety.ytsafety_sys_job_role_mapping (
  `id` bigint NOT NULL,
  `job_code` varchar(20) DEFAULT NULL COMMENT '岗位编码',
  `job_name` varchar(50) DEFAULT NULL COMMENT '岗位名称',
  `role_id` bigint DEFAULT NULL COMMENT '角色主键',
  `role_name` varchar(50) DEFAULT NULL COMMENT '角色名称',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_user` varchar(64) DEFAULT NULL COMMENT '创建人',
  `update_time` datetime DEFAULT NULL COMMENT '修改时间',
  `update_user` varchar(64) DEFAULT NULL COMMENT '修改人',
  `del_flag` tinyint(1) DEFAULT 0 COMMENT '删除标识',
  `version` int DEFAULT 0 COMMENT '修改版本',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='岗位角色映射表';

CREATE TABLE safety.ytsafety_sys_org_factory (
  `id` BIGINT(20) NOT NULL,
  `org_code` VARCHAR(20) NULL COMMENT '组织编码',
  `org_name` VARCHAR(255) NULL COMMENT '组织名称',
  `factory_id` BIGINT(20) NULL COMMENT '厂区编码',
  `factory_code` VARCHAR(100) NULL COMMENT '厂区编码',
  `factory_name` VARCHAR(50) NULL COMMENT '厂区名称',
  `create_time` DATETIME NULL COMMENT '创建时间',
  `create_user` VARCHAR(64) NULL COMMENT '创建人',
  `update_time` DATETIME NULL COMMENT '修改时间',
  `update_user` VARCHAR(64) NULL COMMENT '修改人',
  `del_flag` TINYINT(1)  DEFAULT 0 COMMENT '删除标识',
  `version` INT  DEFAULT 0 COMMENT '修改版本',
  PRIMARY KEY (`id`)) ENGINE=InnoDB  DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT = '组织厂区色映射表';

CREATE TABLE safety.ytsafety_sys_log (
  `id` varchar(50) NOT NULL COMMENT '日志主键',
  `log_type` int DEFAULT NULL COMMENT '日志类型',
  `log_content` varchar(2000) DEFAULT NULL COMMENT '日志内容',
  `method` varchar(500) DEFAULT NULL COMMENT '方法名称',
  `operate_type` int DEFAULT NULL COMMENT '操作类型',
  `request_url` varchar(500) DEFAULT NULL COMMENT '请求URL',
  `request_type` varchar(10) DEFAULT NULL COMMENT '请求类型',
  `request_param` text DEFAULT NULL COMMENT '请求参数',
  `ip` varchar(32) DEFAULT NULL COMMENT '操作IP',
  `userid` varchar(50) DEFAULT NULL COMMENT '用户ID',
  `username` varchar(50) DEFAULT NULL COMMENT '用户名',
  `cost_time` bigint DEFAULT NULL COMMENT '耗时',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(50) DEFAULT NULL COMMENT '创建人',
  `tenant_id` int DEFAULT NULL COMMENT '租户ID',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='系统操作日志表';

CREATE TABLE safety.ytsafety_sys_inteface_log (
  `id` BIGINT(20) NOT NULL,
  `third_system` VARCHAR(64) NULL COMMENT '第三方系统名称',
  `api_code` VARCHAR(64) NULL COMMENT '接口编码/业务标识',
  `api_name` VARCHAR(255) NULL COMMENT '接口名称',
  `request_url` VARCHAR(512) NULL COMMENT '请求地址',
  `request_method` VARCHAR(50) NULL COMMENT '请求方式',
  `request_content` LONGTEXT NULL COMMENT '请求参数',
  `response_content` LONGTEXT NULL COMMENT '响应结果',
  `response_status` INT NULL COMMENT 'HTTP响应状态码',
  `cost_time` BIGINT NULL COMMENT '耗时',
  `error_info` TEXT NULL COMMENT '异常信息',
  `retry_num` INT NULL COMMENT '重试次数',
  `create_time` DATETIME NULL COMMENT '创建时间',
  PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT = '三方接口日志';

CREATE TABLE safety.ytsafety_api_route_config (
  `id` BIGINT(20) NOT NULL,
  `system_name` VARCHAR(100) NULL COMMENT '三方系统名称',
  `route_code` VARCHAR(50) NULL COMMENT '路由编码',
  `sys_url` VARCHAR(500) NULL COMMENT '系统地址',
  `inteface_path` VARCHAR(500) NULL COMMENT '接口路径',
  `interface_name` VARCHAR(100) NULL COMMENT '接口名称',
  `interface_server` VARCHAR(50) NULL COMMENT '接口服务',
  `interface_method` VARCHAR(50) NULL COMMENT '请求方式',
  `Interface_status` TINYINT(1) NULL COMMENT '接口状态',
  `Interface_remark` VARCHAR(1000) NULL COMMENT '接口说明',
  `interface_account` VARCHAR(100) NULL COMMENT '接口账号',
  `interface_pwd` VARCHAR(100) NULL COMMENT '接口密码',
  `create_time` DATETIME NULL COMMENT '创建时间',
  `create_user` VARCHAR(64) NULL COMMENT '创建人',
  `update_time` DATETIME NULL COMMENT '修改时间',
  `update_user` VARCHAR(64) NULL COMMENT '修改人',
  `del_flag` TINYINT(1)  DEFAULT 0 COMMENT '删除标识',
  `version` INT  DEFAULT 0 COMMENT '修改版本',
  PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT = '统一接口路由表';
  
